parameters.query:
=query (
 $filter: IssueFilter
) {
 issues(
 first: 50
 filter: $filter
 ) {
 nodes {
 id
 identifier
 title
 description
 url
 createdAt
 updatedAt
 assignee {
 name
 }
 comments(first: 50) {
 nodes {
 id
 createdAt
 user {
 displayName
 }
 body
 }
 }
 }
 }
}

parameters.jsCode:
function collectSentimentDetails({ issues, previousState, issue }) {
  const state =
    previousState === null ? { index: 0, issues: [] } : JSON.parse(JSON.stringify(previousState));
  if (
    !Array.isArray(issues) ||
    issues.length > 50 ||
    new Set(issues.map((i) => i.id)).size !== issues.length
  )
    throw new Error("Expected the source first50 unique Linear issues.");
  if (previousState !== null) {
    const expected = issues[state.index];
    if (
      !expected ||
      !issue ||
      issue.id !== expected.id ||
      !Array.isArray(issue.comments?.nodes) ||
      issue.comments.nodes.length > 50
    )
      throw new Error("Linear issue detail does not match the selected issue.");
    for (const k of ["id", "identifier", "title", "createdAt", "updatedAt"])
      if (typeof issue[k] !== "string" || !issue[k])
        throw new Error("Linear issue metadata is incomplete.");
    const text = issue.comments.nodes
      .map((c) => {
        if (typeof c.body !== "string" || typeof c.createdAt !== "string")
          throw new Error("Linear comment content is incomplete.");
        return (
          (c.user?.displayName ?? c.user?.name ?? "Unknown author") +
          " commented on " +
          c.createdAt +
          ":\n" +
          c.body
        );
      })
      .join("---\n");
    if (!text.trim())
      throw new Error("The source Information Extractor needs nonempty comment text.");
    state.issues.push({
      id: issue.id,
      identifier: issue.identifier,
      title: issue.title,
      url: issue.url,
      createdAt: issue.createdAt,
      updatedAt: issue.updatedAt,
      assignee: issue.assignee ?? null,
      commentText: text,
    });
    state.index++;
  }
  return {
    state,
    more: state.index < issues.length,
    issueId: issues[state.index]?.id ?? "unused-complete",
  };
}

const items = $input.all(),
  issues = items.map((i) => i.json);
return items.map((item, index) => ({
  json: collectSentimentDetails({ issues, previousState: { index, issues: [] }, issue: item.json })
    .state.issues[0],
  pairedItem: { item: index },
}));

function parseSentimentText(text) {
  if (typeof text !== "string") throw new Error("Sentiment completion is not text.");
  const result = JSON.parse(text.trim().replace(/^```(?:json)?\s*|\s*```$/g, ""));
  if (
    !result ||
    typeof result !== "object" ||
    Array.isArray(result) ||
    !["positive", "negative", "neutral"].includes(result.sentiment) ||
    (result.sentimentSummary !== undefined && typeof result.sentimentSummary !== "string") ||
    Object.keys(result).some((k) => !["sentiment", "sentimentSummary"].includes(k))
  )
    throw new Error(
      "Expected sentiment positive/negative/neutral and optional text sentimentSummary.",
    );
  return { sentiment: result.sentiment, sentimentSummary: result.sentimentSummary ?? "" };
}

const results = $input.all(),
  issues = $("Validate Issue Threads").all();
if (results.length !== issues.length) throw new Error("Sentiment count differs.");
return results.map((item, index) => ({
  json: { ...issues[index].json, ...parseSentimentText(JSON.stringify(item.json.output)) },
  pairedItem: { item: index },
}));

const source = $("Copy of Issue").item.json,
  rows = $input
    .all()
    .map((i) => i.json)
    .filter((row) => row.id);
if (rows.length > 1) throw new Error("Issue ID must uniquely identify an Airtable row.");
const current = rows[0]?.["Current Sentiment"] ?? rows[0]?.fields?.["Current Sentiment"];
if (current !== undefined && typeof current !== "string")
  throw new Error("Previous sentiment is not text.");
return [{ json: { ...source, previousSentiment: current ?? "N/A" }, pairedItem: { item: 0 } }];

function escapeSentimentSlack(text) {
  return text.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
function prepareSentimentNotices({ events, issueUrlBase }) {
  if (
    !Array.isArray(events) ||
    typeof issueUrlBase !== "string" ||
    !/^https:\/\/linear\.app\/[a-zA-Z0-9_-]+\/issue\/$/.test(issueUrlBase)
  )
    throw new Error("Configure the Linear organization issue URL.");
  const seen = new Set(),
    transitions = [];
  for (const event of events) {
    const f = event.fields;
    if (!f || typeof f !== "object") throw new Error("Airtable event fields are missing.");
    if (f["Previous Sentiment"] === "Negative" || f["Current Sentiment"] !== "Negative") continue;
    for (const key of ["Issue ID", "Issue Title", "Last Modified"])
      if (typeof f[key] !== "string" || !f[key])
        throw new Error("Negative transition metadata is incomplete.");
    if (
      !/^\d{4}-\d\d-\d\dT/.test(f["Last Modified"]) ||
      !Number.isFinite(Date.parse(f["Last Modified"]))
    )
      throw new Error("Last Modified must be an Airtable time field.");
    if (f.Summary !== undefined && typeof f.Summary !== "string")
      throw new Error("Airtable summary is not text.");
    const key = f["Issue ID"] + ":" + f["Last Modified"];
    if (seen.has(key)) continue;
    seen.add(key);
    transitions.push({ ...f });
  }
  const chunks = [],
    header = {
      type: "section",
      text: {
        type: "mrkdwn",
        text: ":rotating_light: The following issues transitioned to Negative Sentiment",
      },
    },
    divider = { type: "divider" };
  let blocks = [header, divider];
  for (const f of transitions) {
    const url = issueUrlBase + encodeURIComponent(f["Issue ID"]),
      link = "*<" + url + "|" + escapeSentimentSlack(f["Issue ID"]) + ">* ";
    if (link.length > 3000) throw new Error("Linear issue link exceeds one Slack section.");
    let segment = link;
    const parts = [];
    for (const character of f["Issue Title"] + "\n" + (f.Summary ?? "")) {
      const token = escapeSentimentSlack(character);
      if (segment.length + token.length > 3000) {
        parts.push(segment);
        segment = "";
      }
      segment += token;
    }
    if (segment) parts.push(segment);
    for (const text of parts) {
      if (blocks.length === 50) {
        chunks.push({ blocks });
        blocks = [header, divider];
      }
      blocks.push({ type: "section", text: { type: "mrkdwn", text } });
    }
  }
  if (blocks.length > 2) chunks.push({ blocks });
  return {
    messages: chunks.map((chunk, i) => ({
      ...chunk,
      text:
        transitions.length +
        " issues transitioned to Negative Sentiment" +
        (chunks.length > 1 ? " (" + (i + 1) + "/" + chunks.length + ")" : ""),
    })),
    count: transitions.length,
  };
}

const items = $input.all(),
  plan = prepareSentimentNotices({
    events: items.map((i) => ({ fields: i.json.fields })),
    issueUrlBase: items[0].json.issueUrlBase,
  });
return plan.messages.map((message) => ({ json: message, pairedItem: { item: 0 } }));
